class Gradebook:
    def __init__(self) -> None:
        self.assignments = {}  # name -> (weight, kind)
        self.grades = {}  # student -> {assignment -> grade}

    def add_assignment(self, name: str, weight: float, kind: str = "homework") -> None:
        """kind is "homework" or "quiz"."""
        self.assignments[name] = (weight, kind)

    def record(self, student: str, assignment: str, grade: float) -> None:
        if student not in self.grades:
            self.grades[student] = {}
        self.grades[student][assignment] = grade

    def average(self, student: str) -> float:
        if student not in self.grades:
            # If student has no grades at all, compute average with all assignments as 2.0
            total_weight = 0.0
            weighted_sum = 0.0
            for assignment_name, (weight, kind) in self.assignments.items():
                total_weight += weight
                weighted_sum += 2.0 * weight
            if total_weight == 0.0:
                return 2.0
            return round(weighted_sum / total_weight, 2)

        # Get all assignments for this student
        student_grades = self.grades[student]

        # Separate homework and quiz assignments
        homework_assignments = []
        quiz_assignments = []

        for assignment_name, (weight, kind) in self.assignments.items():
            if kind == "homework":
                homework_assignments.append((assignment_name, weight))
            elif kind == "quiz":
                quiz_assignments.append((assignment_name, weight))

        # Calculate weighted sum and total weight
        weighted_sum = 0.0
        total_weight = 0.0

        # Process homework assignments (all included)
        for assignment_name, weight in homework_assignments:
            grade = student_grades.get(assignment_name, 2.0)
            weighted_sum += grade * weight
            total_weight += weight

        # Process quiz assignments (drop lowest if more than one)
        if len(quiz_assignments) > 0:
            quiz_grades = []
            for assignment_name, weight in quiz_assignments:
                grade = student_grades.get(assignment_name, 2.0)
                quiz_grades.append((grade, weight, assignment_name))

            if len(quiz_grades) > 1:
                # Find the lowest grade (if tie, drop one occurrence)
                # Sort by grade, then drop the first one
                quiz_grades.sort(key=lambda x: x[0])
                # Drop the lowest grade
                for i in range(1, len(quiz_grades)):
                    grade, weight, _ = quiz_grades[i]
                    weighted_sum += grade * weight
                    total_weight += weight
            else:
                # Only one quiz, include it
                grade, weight, _ = quiz_grades[0]
                weighted_sum += grade * weight
                total_weight += weight

        # Handle case where there are no assignments
        if total_weight == 0.0:
            return 2.0

        result = weighted_sum / total_weight
        return round(result, 2)
